733	    const totals: Record<number, number> = {};
734	    for (const p of this.periods()) totals[p.id] = 0;
735	    const closed = new Map(this.periods().filter((p) => p.closed).map((p) => [p.id, p.closedTotal ?? '0.00']));
736	    for (const person of this.people()) {
737	      for (const c of person.claims) {
738	        if ((c.status !== 'OPEN' && c.status !== 'SETTLED') || c.due === null) continue;
739	        if (person.held && c.status === 'OPEN') continue;
740	        const period = periodOf(this.periods(), c.date);
741	        if (period && !closed.has(period.id)) totals[period.id] += cents(c.due);
742	      }
743	    }
744	    const shown: Record<number, string> = {};
745	    for (const id of Object.keys(totals)) shown[+id] = closed.get(+id) ?? (totals[+id] / 100).toFixed(2);
