775	  protected async save(e: Event): Promise<void> {
776	    e.preventDefault();
777	    if (this.busy) return;
778	    this.error.set('');
779	    const sheet = this.session.sheet();
780	    if (!sheet) return;
781	    const name = this.name().trim();
782	    const from = this.from().trim() || (this.session.today() ?? '');
783	    const to = this.to().trim();
